code.cpp:
class Solution {
public:
    int maxIncreaseKeepingSkyline(vector<vector<int>>& grid) {
        int n = (int)grid.size();
        vector<int> rowMax(n, 0), colMax(n, 0);
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > rowMax[r]) rowMax[r] = grid[r][c];
                if (grid[r][c] > colMax[c]) colMax[c] = grid[r][c];
            }
        }
        int total = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int limit = rowMax[r] < colMax[c] ? rowMax[r] : colMax[c];
                total += limit - grid[r][c];
            }
        }
        return total;
    }
};
